macro.command:
// Draught of the Second Breath
// isDamaged, while the effect lasts: the blow that would drop the drinker to 0 leaves them at half their hit
// point maximum; later ones leave them at 1 and are counted. When the effect ends, a level of exhaustion for each.
const FLAG = "secondBreath";
const name = macroItem?.name ?? "Draught of the Second Breath";
const say = (content) => ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor }), content: `<strong>${name}</strong>: ${content}` });

if (args[0] === "off") {
  const lastArg = args.at(-1);
  const saves = foundry.utils.getProperty(lastArg?.efData ?? {}, `flags.midi-qol.${FLAG}.saves`) ?? 0;
  if (saves < 1) return;
  const exhaustion = Math.min(6, (actor.system.attributes.exhaustion ?? 0) + saves);
  const updates = { "system.attributes.exhaustion": exhaustion };
  if (actor.isOwner) await actor.update(updates);
  else await MidiQOL.socket().executeAsGM("updateActor", { actorUuid: actor.uuid, updates });
  await say(`the second breath runs out: ${actor.name} gains ${saves} level${saves > 1 ? "s" : ""} of exhaustion.`);
  return;
}
if (args[0]?.tag !== "TargetOnUse" || args[0].macroPass !== "isDamaged") return;

const di = workflow?.damageItem;
if (!di || di.oldHP < 1 || di.newHP > 0) return;
const effect = actor.effects.find(e => e.getFlag("midi-qol", FLAG) !== undefined);
if (!effect) return;
const state = effect.getFlag("midi-qol", FLAG);

// Damage that leaves exactly 1 hit point, temporary hit points spent first.
const useDetail = MidiQOL.configSettings().useDamageDetail;
const base = useDetail ? di.totalDamage : di.hpDamage;
const leaveOne = useDetail ? (di.oldTempHP ?? 0) + di.oldHP - 1 : di.oldHP - 1;
MidiQOL.modifyDamageBy({ damageItem: di, value: leaveOne - base, type: "none", reason: name });
di.newHP = 1;

let update;
if (!state.risen) {
  // the first blow: rise with half the hit point maximum
  const half = Math.max(1, Math.floor(actor.system.attributes.hp.max / 2));
  if (half > 1) MidiQOL.modifyDamageBy({ damageItem: di, value: -(half - 1), type: "healing", reason: name });
  di.newHP = half;
  update = { risen: true, saves: state.saves ?? 0 };
  await say(`${actor.name} draws a second breath and stays standing.`);
} else {
  update = { risen: true, saves: (state.saves ?? 0) + 1 };
  await say(`the draught holds ${actor.name} at 1 hit point.`);
}
await MidiQOL.socket().executeAsGM("updateEffects", { actorUuid: actor.uuid, updates: [{ _id: effect.id, [`flags.midi-qol.${FLAG}`]: update }] });
